# 교통사고 목 통증, 편타손상(목 염좌). 실행: python3 tools/content/whiplash.py
import os,sys; sys.path.insert(0,os.path.join(os.path.dirname(os.path.abspath(__file__)),".."))
from pb import *
KP=("질병관리청 국가건강정보포털","https://health.kdca.go.kr")
def T(name,sub,who,feat,sign,exam,dir_,todo):
    return {"name":name,"sub":sub,"rows":[("이런 분에게 많아요",who),("나타나는 모습",feat),("함께 오는 몸의 신호",sign),("진찰에서 보이는 모습",exam),("치료 방향",dir_),("오늘부터 해 볼 것",todo)]}

build("whiplash",dict(
desc="교통사고 뒤 목이 뻣뻣하고 아픈 편타손상(목 염좌)의 원리, 응급실이 먼저인 신호, 자동차보험 한방 진료와 침·초음파 가이드 약침·추나·한약 관리를 인천 서구 365스마일한의원이 정리했습니다.",
answer="편타손상은 차가 부딪치는 순간 머리가 채찍처럼 앞뒤로 휘둘리며 목의 근육·인대·관절이 늘어나 생기는 목 염좌로, 사고 당일보다 다음 날이나 이틀 뒤에 목이 더 뻣뻣해지는 일이 흔합니다. 의식이 흐려지거나, 두통이 심하고 토하거나, 팔다리에 힘이 빠지면 한의원보다 응급실에서 CT 같은 영상 검사를 먼저 받으세요. 인천 서구 365스마일한의원은 자동차보험(자보)으로 진료하며, 병원 검사와 한의원 치료를 함께 받으실 수 있습니다. 골절과 신경 손상이 없는 목 통증은 침, 초음파 가이드 약침, 추나 요법, 한약으로 관리합니다.",
sections=[
("check","사고 뒤 내 목 상태를 확인해 보세요",CHECK(["고개를 좌우로 돌리면 어느 지점에서 걸리듯 멈춘다","뒷목에서 어깨 위쪽까지 돌덩이처럼 단단하게 뭉쳤다","아침에 일어날 때 베개에서 머리를 들기가 힘들다","운전석에서 뒤를 돌아보는 동작이 겁난다","뒤통수가 묵직하고 눈 뒤까지 당긴다","날개뼈 안쪽이 쑤시고 팔이 무겁다"])),
("why","목이 채찍처럼 꺾이면 무엇이 다치나요?",P("뒤에서 추돌을 당하면 몸통은 좌석에 밀려 앞으로 나가는데 머리는 잠깐 제자리에 남아, 목이 S자로 휘었다가 앞으로 튕겨 나갑니다. 이 순간 목 앞쪽 근육은 갑자기 늘어나고 뒤쪽 작은 관절(후관절)은 눌리며, 몸은 다친 곳을 지키려고 주변 근육을 단단히 조여 목을 굳힙니다.")+"\n"+P("1995년 캐나다 퀘벡 특별위원회(Quebec Task Force)는 이런 증상을 <b>편타손상 관련 장애(WAD)</b>라 부르고 정도를 나누었습니다.")+"\n"+UL([B("1단계","목이 아프고 뻣뻣하며 누르면 아프지만 다른 이상은 없습니다."),B("2단계","목이 움직이는 범위가 줄고 근육·관절에 뚜렷한 압통이 있습니다."),B("3단계","팔 저림, 힘 약화, 반사 이상 같은 신경 증상이 함께 있습니다."),B("4단계","목뼈 골절이나 탈구가 있습니다.")])+"\n"+P("한의원에서는 주로 1~2단계를 관리하고, 3단계는 신경 검사와 함께 보며, 4단계는 정형외과·신경외과 치료가 먼저입니다.")),
("red","응급실에서 CT부터 찍어야 하는 신호",UL(["의식을 잃었거나, 사고 뒤 멍하고 말이 어눌하며 깨우기 힘들 만큼 졸리다","두통이 점점 심해지고 여러 번 토한다","팔다리가 마비된 듯 힘이 빠지거나 감각이 둔해졌다","목뼈 한가운데를 누르면 심하게 아프고 고개를 거의 돌리지 못한다","65세 이상이거나, 차가 전복되었거나 큰 속도로 부딪쳤다"])+"\n"+P("하나라도 해당하면 <b>119나 응급실</b>로 가서 CT 같은 영상 검사를 먼저 받으세요. 캐나다 경추 규칙(Canadian C-spine rule)도 나이, 사고 기전, 팔다리 저림, 고개를 좌우 45도 돌릴 수 있는지로 영상 검사 필요성을 판단합니다.")),
("km","한의학은 편타손상을 어떻게 보나요?",P("한의학은 부딪치거나 삐어서 생긴 병을 <b>타박·염좌(打撲·捻挫)</b>로 다루었습니다. 갑작스러운 힘에 근육과 힘줄(筋)이 상하면 그 자리의 기혈이 막혀 아프고 붓는다고 보았고, 목 뒤를 지나는 방광경·담경이 막히면 뒤통수와 어깨까지 당긴다고 풀이했습니다.")+"\n"+P("다친 직후에는 막힌 혈을 풀어 붓기를 내리는 데, 몇 주 뒤 남는 뻣뻣함에는 굳은 힘줄을 부드럽게 하는 데, 오래가는 통증에는 약해진 기혈을 채우는 데 무게를 둡니다.")),
("types","내 목 통증은 어떤 유형일까?",CARDS([
T("급성 어혈","다친 자리가 화끈한 유형","사고 뒤 1~2주 안에 오신 분","한 자리를 누르면 펄쩍 뛸 만큼 아프고 밤에 욱신거린다","목 옆 붓기, 열감","압통점이 뚜렷하고 혀 가장자리가 어두움","막힌 혈을 풀어 붓기를 내리는 방향 (복원활혈탕 계열)","처음 2~3일은 아픈 곳에 냉찜질을 10분 정도씩 해 보세요."),
T("근육 긴장","목 전체가 굳은 유형","책상 일을 오래 하거나 원래 목이 뻣뻣하던 분","고개를 돌릴 때 한쪽이 끝까지 가지 않고 아침에 특히 굳는다","뒤통수 두통, 어깨 뭉침","목 뒤 근육이 띠처럼 단단히 만져짐","굳은 근육과 힘줄을 풀어 주는 방향 (갈근탕 계열)","모니터를 눈높이로 올리고 한 시간마다 어깨를 천천히 돌려 주세요."),
T("풍한습","흐린 날 더 쑤시는 유형","사고 뒤 한 달 넘게 통증이 남은 분","비가 오거나 에어컨 바람을 쐬면 뒷목이 시리고 무겁다","팔이 저리고 몸이 무거움","혀에 흰 이끼가 끼고 맥이 느림","찬 기운과 습기를 걷어 경락을 소통시키는 방향 (소경활혈탕 계열)","목에 찬 바람이 닿지 않게 스카프를 둘러 보세요.")],
intro="골절과 신경 손상이 배제된 뒤의 한의학적 구분이며, 두 유형이 겹치는 일도 많습니다.")),
("exam","한의원에서는 어떻게 진찰하나요?",UL([B("사고 상황","추돌 방향, 머리 받침대 높이, 부딪칠 때 고개를 돌리고 있었는지 여쭙니다."),B("영상 결과","병원에서 찍은 X선·CT·MRI 결과가 있으면 가져와 주세요."),B("움직임과 압통","고개를 숙이고 돌리는 각도를 재고, 아픈 근육과 관절을 짚어 봅니다."),B("신경과 초음파","팔 저림, 손힘, 반사를 살피고, 필요하면 초음파로 근육과 인대의 붓기를 확인합니다."),B("자동차보험","보험사 사고 접수번호를 알려 주시면 자동차보험으로 진료합니다.")])),
("treat","침·약침·추나·한약 치료는 어떻게 하나요?",H3("1. 침 치료")+"\n"+UL([B("풍지(風池)","뒤통수 아래 머리카락 경계에서 목 가운데 굵은 근육 바깥쪽 오목한 곳입니다."),B("견정(肩井)","목 아래 툭 튀어나온 뼈와 어깨 끝을 이은 선의 한가운데입니다."),B("후계(後谿)","주먹을 쥐었을 때 새끼손가락 쪽 손바닥 주름 끝에 생기는 오목한 곳입니다."),B("낙침혈(落枕穴)","손등에서 둘째·셋째 손가락뼈 사이, 손가락 마디에서 손목 쪽으로 조금 올라간 곳입니다. 침을 놓은 채 고개를 천천히 움직이는 운동침에 씁니다.")])+"\n"+H3("2. 약침·초음파 가이드 약침과 추나 요법")+"\n"+P("약침은 일반 약침과 초음파 가이드 약침을 모두 시행하며, 아픈 부위의 깊이와 주변 구조에 따라 진찰 후 골라 씁니다. 초음파 가이드 약침은 초음파 화면으로 바늘 끝을 확인하면서 놓는 방식입니다. 목 옆과 뒤쪽에 겹겹이 쌓인 근육 층과 그 사이를 지나는 혈관·신경을 화면에서 구분해 보고, 다쳐서 붓거나 굳은 근육 층과 후관절 주변에 바늘 끝이 닿았는지 확인하며 약침을 놓습니다. 영상 검사로 골절과 불안정성이 없음을 확인한 뒤 진찰 후 추나 요법을 시행하며, 사고 직후에는 부드러운 이완부터 시작하고, 붓기가 가라앉으면 굳은 근육을 데우는 온열 요법도 더합니다.")+"\n"+H3("3. 한약")+"\n"+P("사고 뒤 지난 시간과 유형에 맞춰 탕약 위주로 처방하며, 자동차보험으로 처방할 수 있는 범위를 내원 때 안내합니다. 임신 중이거나 간·신장 질환이 있었던 분은 진료 때 꼭 알려 주세요. 확인 후 안전한 약재로 처방합니다. 병원에서 받은 진통제나 근이완제는 알려 주시면 확인해 처방합니다.")),
("road","치료는 어떤 순서로 진행되나요?",ROAD([("사고 직후","응급 신호를 확인하고, 필요하면 병원 영상 검사를 먼저 받습니다."),("1~2주","붓기와 통증을 가라앉히는 침과 약침 위주로 치료합니다."),("3~6주","고개 돌리는 범위를 넓히며 추나 요법과 온열 요법을 더합니다."),("6주 이후","남은 뻣뻣함을 관리하고, 3개월 넘게 이어지면 원인을 다시 점검합니다.")])),
("home","집에서 할 수 있는 목 관리",UL([B("조금씩 움직이기","통증이 허락하는 범위에서 고개를 천천히 움직이는 편이 오래 고정하는 것보다 낫습니다. 목 보조기는 병원에서 권한 기간만 하세요."),B("턱 당기기","등을 벽에 대고 서서 턱을 뒤로 살짝 당겨 5초 버티기를 10번씩, 하루 두세 번 합니다."),B("찜질 순서","붓고 화끈한 처음 2~3일은 냉찜질, 그 뒤에는 따뜻한 수건으로 온찜질을 합니다."),B("혈자리 지압","뒷목이 당길 때 엄지로 풍지혈을 5초씩 지그시 눌렀다 떼기를 몇 번 반복해 보세요.")])),
("other","다른 진료가 함께 필요한 경우",UL(["팔이 저리고 손힘이 빠지면 신경외과·정형외과에서 MRI로 목 디스크와 신경 압박을 확인하세요.","머리를 부딪쳤거나 어지럼·메스꺼움이 계속되면 신경과 진료를 함께 받으세요."])),
],
faq=[("사고 당일엔 괜찮았는데 다음 날 목이 아파요. 늦게 생겨도 사고 때문인가요?","편타손상은 하루 이틀 뒤 통증이 커지는 일이 흔합니다."),("병원 치료를 받으면서 한의원 치료도 받을 수 있나요?","가능합니다. 병원 검사와 한의원 치료를 함께 받으시되, 받은 검사와 약을 알려 주세요."),("자동차보험으로 진료받으려면 무엇이 필요한가요?","보험사에 사고를 접수하고 받은 접수번호를 알려 주시면 됩니다."),("목 보조기를 계속 차야 하나요?","병원에서 권한 기간이 지나면 조금씩 움직이는 편이 덜 굳습니다."),("사고 직후에도 추나 요법을 받을 수 있나요?","영상 검사로 골절이 없는 것을 확인한 뒤 진찰 후 시행하며, 처음에는 부드러운 이완부터 합니다."),("초음파 가이드 약침은 일반 약침과 무엇이 다른가요?","초음파 화면으로 근육 층과 바늘 끝을 보면서 놓습니다."),("얼마나 다녀야 하나요?","대개 몇 주에 걸쳐 좋아지지만 사람마다 달라 경과를 보며 안내합니다."),("목이 아픈데 두통과 어지럼도 있어요.","목 근육 긴장 때문일 수도 있지만, 두통이 심해지거나 토하면 바로 응급실로 가세요.")],
refs=[("Spitzer WO, et al. Scientific monograph of the Quebec Task Force on Whiplash-Associated Disorders. Spine, 1995;20(8 Suppl):1S-73S",None),("Stiell IG, et al. The Canadian C-spine rule for radiography in alert and stable trauma patients. JAMA, 2001;286(15):1841-1848",None),KP]))
